	public static BindingSet withLateralDomain(BindingSet bindings, Set<String> domain, Set<String> privateInputs,
			BindingSet currentEntry, List<TupleParameterEdge> edges, QueryEvaluationContext context) {
		MutableBindingSet copy = GraphFrameBindings.preserve(bindings, context.createBindingSet(bindings));
		BindingFrame frame = BindingFrame.withLateralDomain(from(bindings), domain, privateInputs);
		for (TupleParameterEdge edge : edges) {
			Map<String, Value> arguments = new HashMap<>();
			for (String name : edge.names) {
				if (bindings.getValue(name) == null && currentEntry.getValue(name) == null) {
					Value value = currentEntryWithheldInput(currentEntry, name);
					if (value != null) {
						arguments.put(name, value);
					}
				}
			}
			frame = BindingFrame.tupleArguments(frame, edge.grant.owner, arguments, edge.names);
		}
		return attach(copy, frame);
	}

	/** Removes private LATERAL names from a projection body without exposing them as withheld inputs. */
	public static BindingSet hideLateralProjectionInputs(BindingSet bindings, Set<String> sourceNames,
			QueryEvaluationContext context) {
		Set<String> privateInputs = lateralPrivateInputs(bindings);
		if (privateInputs.isEmpty() || sourceNames.containsAll(privateInputs)) {
			return bindings;
		}
		Set<String> hidden = new HashSet<>(privateInputs);
		hidden.removeAll(sourceNames);
		MutableBindingSet copy = GraphFrameBindings.preserve(bindings, context.createBindingSet(bindings));
		for (String name : hidden) {
			copy.removeBinding(name);
		}
		return attach(copy, from(bindings).withoutInputs(hidden));
	}

