	public static BindingSet push(Scope owner, BindingSet semanticEntry, BindingSet probeSeed,
			QueryEvaluationContext context, BindingFrameReplay.Domain replay) {
		Map<String, Value> probes = new HashMap<>(probeSeed.size() * 2);
		for (Binding binding : probeSeed) {
			if (binding.getValue() != null) {
				probes.put(binding.getName(), binding.getValue());
			}
		}
		MutableBindingSet logical = GraphFrameBindings.preserve(semanticEntry, context.createBindingSet(semanticEntry));
		return attach(logical, new BindingFrame(owner, from(semanticEntry), probes, false, replay));
	}

